const WORKER_CODE_SNIPPET = `// Cloudflare Worker — DeepL API Proxy
// Paste this into a new Cloudflare Worker to bypass browser CORS restrictions.
//
// How it works:
// 1. Browser sends POST request to your Worker URL with Authorization header
// 2. Worker forwards the request to DeepL API
// 3. Worker returns DeepL response with CORS headers
//
// Setup:
// 1. Go to Cloudflare Dashboard → Workers & Pages → Create → Create Worker
// 2. Replace the default code with this entire file
// 3. Deploy → Copy the Worker URL
// 4. Paste it into "Custom Proxy URL" field above

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Deepl-Plan',
  'Access-Control-Max-Age': '86400',
};

export default {
  async fetch(request) {
    // CORS preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }

    if (request.method !== 'POST') {
      return new Response(JSON.stringify({ error: 'Method not allowed' }), {
        status: 405,
        headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
      });
    }

    try {
      const plan = request.headers.get('X-Deepl-Plan') === 'pro' ? 'pro' : 'free';
      const targetBase =
        plan === 'free'
          ? 'https://api-free.deepl.com/v2/translate'
          : 'https://api.deepl.com/v2/translate';

      const bodyText = await request.text();
      const forwardHeaders = new Headers();
      forwardHeaders.set('Content-Type', 'application/x-www-form-urlencoded');

      const authHeader = request.headers.get('Authorization');
      if (authHeader) forwardHeaders.set('Authorization', authHeader);

      const deeplResponse = await fetch(targetBase, {
        method: 'POST',
        headers: forwardHeaders,
        body: bodyText,
      });

      const responseBody = await deeplResponse.text();
      const responseHeaders = new Headers({
        ...CORS_HEADERS,
        'Content-Type': deeplResponse.headers.get('content-type') || 'application/json',
      });

      return new Response(responseBody, {
        status: deeplResponse.status,
        headers: responseHeaders,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      return new Response(
        JSON.stringify({ error: 'Proxy error', details: message }),
        {
          status: 502,
          headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
        },
      );
    }
  },
};`;

export default function AdminTranslateSettingsPage() {
  const { adminT } = useI18n();
  const [settings, setSettings] = useState<TranslateSettings>({
    provider: 'mymemory',
    deeplApiKey: '',
    deeplPlan: 'free',
    useCorsProxy: true,
    corsProxyApiKey: '',
    customProxyUrl: '',
  });
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<{ ok: boolean; message: string } | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setSettings(getTranslateSettings());
  }, []);

  const handleSave = () => {
    setSaving(true);
    try {
      saveTranslateSettings(settings);
      toast.success('Translation settings saved');
      setTestResult(null);
    } catch {
      toast.error('Failed to save settings');
    } finally {
      setTimeout(() => setSaving(false), 300);
    }
  };

  const handleTest = async () => {
    if (settings.provider !== 'deepl' || !settings.deeplApiKey.trim()) {
      toast.warning('Please select DeepL and enter an API Key first');
      return;
    }
    setTesting(true);
    setTestResult(null);
    try {
      const result = await testDeepLKey(
        settings.deeplApiKey,
        settings.deeplPlan,
        settings.useCorsProxy,
        settings.corsProxyApiKey,
        settings.customProxyUrl,
      );
      setTestResult(result);
      if (result.ok) {
        toast.success('API Key is valid!');
      } else {
        toast.error('API Key test failed');
      }
    } catch (e) {
      setTestResult({ ok: false, message: String(e) });
      toast.error('Test request failed');
    } finally {
      setTesting(false);
    }
  };

  const handleClearCache = () => {
    clearTranslationCache();
    toast.success('Translation cache cleared');
  };

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[
          { label: adminT('admin.translateSettings') || adminT('admin.translationSettings') },
        ]}
      />

      <div>
        <h1 className="text-2xl font-bold text-foreground">Translation Settings</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Configure your translation service provider and API keys
        </p>
      </div>

      {/* 敏感信息提示 */}
      <Card className="border-amber-500/30 bg-amber-500/5">
        <CardContent className="pt-4 pb-4">
          <div className="flex items-start gap-3">
            <Shield className="size-5 text-amber-500 shrink-0 mt-0.5" />
            <div className="text-sm space-y-1">
              <p className="font-medium text-amber-600 dark:text-amber-500">
                Sensitive Information Notice
              </p>
              <p className="text-muted-foreground">
                This page contains sensitive data (API Key). The API Key is <strong>stored locally in your browser only</strong> and will <strong>never</strong> be synced to GitHub.
              </p>
              <p className="text-muted-foreground">
                Custom translation texts entered by admins <strong>will</strong> be synced to GitHub via <code className="px-1.5 py-0.5 bg-muted rounded text-xs font-mono">data/translations.json</code>.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Provider Selection */}
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Globe className="size-5 text-primary" />
            Translation Provider
          </CardTitle>
          <CardDescription>
            Choose which translation service to use. DeepL offers higher quality and requires an API key.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            <Label>Provider</Label>
            <Select
              value={settings.provider}
              onValueChange={(v) =>
                setSettings({ ...settings, provider: v as 'deepl' | 'mymemory' })
              }
            >
              <SelectTrigger className="max-w-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="mymemory">MyMemory (Free, no API key)</SelectItem>
                <SelectItem value="deepl">DeepL (Higher quality, API key required)</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {settings.provider === 'deepl' && (
            <div className="space-y-4 p-4 rounded-lg border border-border/40 bg-background/40">
              <div className="flex items-center gap-2 text-sm font-medium">
                <Key className="size-4 text-primary" />
                DeepL API Configuration
              </div>

              <div className="space-y-2">
                <Label htmlFor="deepl-key">API Key</Label>
                <Input
                  id="deepl-key"
                  type="password"
                  value={settings.deeplApiKey}
                  onChange={(e) => setSettings({ ...settings, deeplApiKey: e.target.value })}
                  placeholder="e.g. 12345678-1234-1234-1234-123456789abc:fx"
                  className="max-w-md font-mono text-sm"
                />
                <p className="text-xs text-muted-foreground">
                  Get your API key from{' '}
                  <UniversalLink
                    to="https://www.deepl.com/pro-api"
                    target="_blank"
                    rel="noreferrer"
                    className="text-primary hover:underline"
                  >
                    deepl.com/pro-api
                  </UniversalLink>
                  . Free plan includes 500,000 characters/month.
                </p>
              </div>

              <div className="space-y-2">
                <Label>Plan Type</Label>
                <Select
                  value={settings.deeplPlan}
                  onValueChange={(v) =>
                    setSettings({ ...settings, deeplPlan: v as 'free' | 'pro' })
                  }
                >
                  <SelectTrigger className="max-w-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="free">Free Plan (api-free.deepl.com)</SelectItem>
                    <SelectItem value="pro">Pro Plan (api.deepl.com)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* DeepL CORS 限制说明 */}
               <div className="p-3 rounded-md bg-info/10 border border-info/30 text-info/90 text-xs space-y-1">
                 <p className="font-semibold">💡 DeepL &amp; Browser CORS</p>
                 <p>
                   DeepL API does <strong>not</strong> support direct calls from the browser (CORS is blocked).
                   You must use a proxy. <strong>Custom proxy (Cloudflare Worker)</strong> is the most reliable option.
                   If you don&apos;t have one, enable the CORS Proxy below as a fallback.
                 </p>
               </div>

               {/* 自定义代理 URL */}
               <div className="space-y-2">
                 <div className="flex items-center gap-2 text-sm font-medium">
                   <Server className="size-4 text-primary" />
                   Custom Proxy URL (Recommended)
                 </div>
                 <p className="text-xs text-muted-foreground">
                   Enter your Cloudflare Worker or other self-hosted proxy URL. This is the most stable option and bypasses all CORS issues.
                 </p>
                 <div className="flex gap-2">
                   <Input
                     type="url"
                     value={settings.customProxyUrl}
                     onChange={(e) => setSettings({ ...settings, customProxyUrl: e.target.value })}
                     placeholder="https://deepl-proxy.yourname.workers.dev"
                     className="max-w-md font-mono text-sm flex-1"
                   />
                   <Dialog>
                     <DialogTrigger asChild>
                       <Button variant="outline" size="sm">
                         <Code className="size-4 mr-1" />
                         View Worker Code
                       </Button>
                     </DialogTrigger>
                     <DialogContent className="border-border/40 bg-card text-foreground max-w-2xl max-h-[80vh] overflow-hidden flex flex-col">
                       <DialogHeader>
                         <DialogTitle>Cloudflare Worker — DeepL Proxy</DialogTitle>
                         <DialogDescription className="text-muted-foreground">
                           Copy and paste this code into a new Cloudflare Worker. Then paste the Worker URL above.
                         </DialogDescription>
                       </DialogHeader>
                       <div className="flex-1 overflow-auto">
                         <pre className="text-xs bg-background border border-border/40 rounded-md p-3 text-muted-foreground whitespace-pre-wrap break-all">
{WORKER_CODE_SNIPPET}
                         </pre>
                       </div>
                       <DialogFooter className="gap-2">
                         <DialogClose asChild>
                           <Button variant="outline">Close</Button>
                         </DialogClose>
                         <Button
                           size="sm"
                           onClick={() => {
                             navigator.clipboard.writeText(WORKER_CODE_SNIPPET).then(() => {
                               toast.success('Code copied to clipboard');
                             }).catch(() => {
                               toast.error('Copy failed');
                             });
                           }}
                         >
                           <Copy className="size-4 mr-1" />
                           Copy Code
                         </Button>
                       </DialogFooter>
                     </DialogContent>
                   </Dialog>
                 </div>
               </div>

               <div className="flex items-center justify-between max-w-md">
                <div className="space-y-0.5">
                  <Label htmlFor="cors-proxy">Use CORS Proxy</Label>
                  <p className="text-xs text-muted-foreground">
                    Required when DeepL API blocks browser requests due to CORS
                  </p>
                </div>
                <Switch
                  id="cors-proxy"
                  checked={settings.useCorsProxy}
                  onCheckedChange={(v) => setSettings({ ...settings, useCorsProxy: v })}
                />
              </div>

              {settings.useCorsProxy && (
                <div className="space-y-2 pl-4 border-l-2 border-border/40">
                  <Label htmlFor="cors-proxy-key">CORS Proxy API Key</Label>
                  <Input
                    id="cors-proxy-key"
                    type="password"
                    value={settings.corsProxyApiKey}
                    onChange={(e) =>
                      setSettings({ ...settings, corsProxyApiKey: e.target.value })
                    }
                    placeholder="Get a free key from cors.sh"
                    className="max-w-md font-mono text-sm"
                  />
                  <p className="text-xs text-muted-foreground">
                    Get a free temporary key from{' '}
                    <UniversalLink to="https://proxy.cors.sh/">
                      proxy.cors.sh
                    </UniversalLink>
                    . Leave empty for basic anonymous usage (rate limited).
                  </p>
                </div>
              )}

              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleTest}
                  disabled={testing || !settings.deeplApiKey.trim()}
                >
                  {testing ? (
                    <Loader2 className="size-4 mr-2 animate-spin" />
                  ) : (
                    <CheckCircle2 className="size-4 mr-2" />
                  )}
                  Test API Key
                </Button>
              </div>

              {testResult && (
                <div
                  className={`p-3 rounded-md text-sm space-y-2 ${
                    testResult.ok
                      ? 'bg-success/10 border border-success/30 text-success'
                      : 'bg-destructive/10 border border-destructive/30 text-destructive'
                  }`}
                >
                  <div className="flex items-start gap-2">
                    {testResult.ok ? (
                      <CheckCircle2 className="size-4 shrink-0 mt-0.5" />
                    ) : (
                      <AlertTriangle className="size-4 shrink-0 mt-0.5" />
                    )}
                    <span className="break-all">{testResult.message}</span>
                  </div>
                  {/* CORS 失败诊断 */}
                  {!testResult.ok &&
                    !settings.useCorsProxy &&
                    (testResult.message.toLowerCase().includes('failed to fetch') ||
                      testResult.message.toLowerCase().includes('cors') ||
                      testResult.message.toLowerCase().includes('network')) && (
                    <div className="text-xs border-t border-destructive/20 pt-2 space-y-1">
                      <p className="font-semibold">Why this happens:</p>
                      <ul className="list-disc list-inside space-y-0.5 text-muted-foreground">
                        <li>DeepL API does NOT allow direct browser calls (CORS is blocked on their side)</li>
                        <li>"Failed to fetch" usually means the browser blocked the request due to CORS</li>
                        <li>This is expected behavior — not an API key issue</li>
                      </ul>
                      <p className="font-semibold mt-2">Solution:</p>
                      <ul className="list-disc list-inside space-y-0.5 text-muted-foreground">
                        <li>Enable the <strong>"Use CORS Proxy"</strong> toggle above (recommended)</li>
                        <li>Or use MyMemory (free, no key required) — it works directly in the browser</li>
                        <li>Or set up a backend proxy server for DeepL</li>
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          {settings.provider === 'mymemory' && (
            <div className="p-4 rounded-lg border border-border/40 bg-background/40">
              <p className="text-sm text-muted-foreground">
                <strong className="text-foreground">MyMemory</strong> is a free translation service
                that doesn&apos;t require an API key. It&apos;s used as the default fallback.
                Limit: ~5000 characters/day per IP address.
              </p>
            </div>
          )}
        </CardContent>
        <CardFooter className="flex justify-between border-t border-border/40 pt-4">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={handleClearCache}
          >
            Clear Translation Cache
          </Button>
          <Button
            type="button"
            onClick={handleSave}
            disabled={saving}
            className="bg-primary hover:bg-primary/90"
          >
            {saving ? (
              <Loader2 className="size-4 mr-2 animate-spin" />
            ) : (
              <Save className="size-4 mr-2" />
            )}
            Save Settings
          </Button>
        </CardFooter>
      </Card>

      {/* Info */}
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base">How Auto-Translate Works</CardTitle>
        </CardHeader>
        <CardContent className="text-sm text-muted-foreground space-y-2">
          <p>
            <strong className="text-foreground">As-you-type:</strong> When you stop typing in the
            English input field for 500ms, the system automatically translates to Chinese,
            Spanish, and Japanese.
          </p>
          <p>
            <strong className="text-foreground">On blur:</strong> Clicking away from the English
            field triggers an immediate translation.
          </p>
          <p>
            <strong className="text-foreground">Caching:</strong> Translated text is cached
            locally to avoid redundant API calls and stay within rate limits.
          </p>
          <p>
            <strong className="text-foreground">Fallback:</strong> If DeepL fails (invalid key,
            rate limit, network issue), the system automatically falls back to MyMemory.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}
